function demoProject() {
  const sample = freshProject('مثال تطبيقي');
  sample.title = 'طرق حديث مشتركة ومتفرعة';
  sample.matn = '«إنما الأعمال بالنيات» — متن تجريبي قابل للاستبدال';
  const rows = [['النبي ﷺ','ابن عمر','نافع','مالك','الشافعي'],['النبي ﷺ','ابن عمر','نافع','مالك','أحمد'],['أبو هريرة','الأعرج','أبو الزناد','مالك','الشافعي']];
  const identities = new Map();
  rows.forEach((names, index) => {
    const narrators = names.map(name => {
      const key = normalize(name);
      if (!identities.has(key)) identities.set(key, uid('n'));
      const identityId = identities.get(key);
      sample.nodes[identityId] ||= {name,color:'',note:'',manualTier:null,generation:'',isCompiler:false};
      return {occurrenceId:uid('o'),name,identityId};
    });
    sample.chains.push({id:uid('chain'),label:`الطريق ${arabicDigits(index+1)}`,entryDirection:'source-to-compiler',narrators,transmissions:Array(Math.max(0,narrators.length-1)).fill(''),source:{book:index===0?'مثال توضيحي':'',volume:'',page:'',hadith:'',free:''},note:''});
  });
  return sample;
}

