  const focusNode=project.settings.focusNarratorId&&graph.nodes.find(node=>graphIdentityId(node)===project.settings.focusNarratorId),focusPaths=focusNode?new Set(project.chains.map((chain,index)=>chain.narrators.some(item=>item.identityId===project.settings.focusNarratorId)?index:-1).filter(index=>index>=0)):null;if(focusPaths){for(const level of ordered)focusLevel(levels.get(level),focusPaths);alignFocusedSideTails(levels,ordered,focusPaths,parents,nodeById,graph);}
