function validateSelectiveObservation(ids,sharedId){if(!ids.length)return'اختر راوياً واحدًا على الأقل.';if(!sharedId)return'عيّن الراوي المشترك أولًا.';if(ids.includes(sharedId))return'يجب أن يكون الراوي المشترك منفصلًا عن قائمة الرواة المستهدفين.';const missing=[...ids,sharedId].filter(id=>!observationNarratorName(id));if(missing.length)return'تعذر العثور على إحدى هويات الرواة المختارة؛ راجع الاختيار.';const result=selectiveObservationMatches(ids,sharedId);if(!result.matches.length)return result.wrongSide.length?'الرواة المختارون في الجهة الأخرى من ترتيب الإسناد المحفوظ بالنسبة إلى الراوي المشترك.':'لا توجد طرق محفوظة تجمع الاختيار الحالي بالراوي المشترك.';return'';}
