function selectEdge(id,force=false){if(!force&&selected.type==='edge'&&selected.id===id)return clearSelection();const edge=graphData.edges.find(item=>item.id===id);if(!edge)return clearSelection();selected={type:'edge',id};$('.inspector-empty')?.classList.add('hidden');$('nodeInspector').classList.add('hidden');$('edgeInspector').classList.remove('hidden');const meta=project.edges[edgeStorageId(edge)]||{};$('selectedEdgeName').textContent=`${nodeMeta(edge.fromIdentityId||edge.from).name} ← ${nodeMeta(edge.toIdentityId||edge.to).name}`;$('edgeColor').value=meta.color||edgeColors(edge)[0];$('edgeNote').value=meta.note||'';const root=$('edgeTransmissions');root.replaceChildren();for(const segment of edge.segments||[]){const chain=project.chains[segment.chainIndex],field=document.createElement('div');field.className='transmission-field';const label=document.createElement('label');label.textContent=routeDisplayLabel(chain,segment.chainIndex);const input=document.createElement('input');input.setAttribute('list','transmissionWording');input.setAttribute('dir','auto');input.placeholder='مثال: حدثنا، عن، قال';input.value=chain.transmissions?.[segment.segmentIndex]||'';input.dataset.chainId=chain.id;input.dataset.segmentIndex=String(segment.segmentIndex);label.append(input);field.append(label);root.append(field);}updateSelectionStyles();}

function setSaveStatus(state){saveState=state;const element=$('saveStatus');if(!element)return;element.className=`save-status ${state}`;element.textContent=state==='saving'?'جارٍ الحفظ':state==='failed'?'تعذّر الحفظ':'تم الحفظ';}
