function mergeIdentities(source,target){if(!source||!target||source===target)return false;const sourceName=nodeMeta(source).name,targetName=nodeMeta(target).name;if(!confirm(`جمع «${sourceName}» مع «${targetName}»؟ سيُعاملان هوية واحدة في جميع الطرق، مع بقاء بيانات الطرق منفصلة.`))return false;const backup=structuredClone(project);project.chains.forEach(chain=>chain.narrators.forEach(item=>{if(item.identityId===source)item.identityId=target;}));const sourceMeta=nodeMeta(source),targetMeta=nodeMeta(target);if(sourceMeta.note&&!targetMeta.note)targetMeta.note=sourceMeta.note;if(project.settings.focusNarratorId===source)project.settings.focusNarratorId=target;delete project.nodes[source];delete project.positions[source];selected={type:'node',id:target};try{assertAcyclic(project);prune();draw();selectNode(target,true);toast('جُمعت الهويتان مع بقاء جميع سجلات الطرق.');return true;}catch(error){project=backup;selected={type:'node',id:source};draw();selectNode(source,true);toast(`تعذر الجمع ولم يتغير المشروع: ${error.message}`);return false;}}
function mergeSelected(){const target=$('mergeTarget').value,source=selected.id;if(!target)return toast('اختر هوية أخرى أولًا؛ لم يتغير شيء.');mergeIdentities(source,target);}
